     1	//! Onboarding issuers and issuing credentials on their behalf.
     2	
     3	use ed25519_dalek::{SigningKey, VerifyingKey};
     4	use serde_json::{json, Value};
     5	use thiserror::Error;
     6	
     7	use crate::credential::{self, Disclosure, CREDENTIALS_CONTEXT};
     8	use crate::resolver::{ResolveError, Resolver};
     9	use crate::store::{CredentialRecord, OnboardedIssuer, Store};
    10	
    11	#[derive(Debug, Error)]
    12	pub enum OnboardError {
    13	    #[error(transparent)]
    14	    Resolve(#[from] ResolveError),
    15	    #[error("{0} publishes no assertion key")]
    16	    NoAssertionKey(String),
    17	}
    18	
    19	/// Approves an issuer: resolves its DID and records it with its document.
    20	pub fn onboard(
    21	    resolver: &Resolver,
    22	    store: &Store,
    23	    did: &str,
    24	    name: &str,
    25	    onboarded_at: &str,
    26	) -> Result<OnboardedIssuer, OnboardError> {
    27	    let document = resolver.resolve(did)?;
    28	    if document.assertion_method.is_empty() {
    29	        return Err(OnboardError::NoAssertionKey(did.to_string()));
    30	    }
    31	    let record = OnboardedIssuer {
    32	        did: did.to_string(),
    33	        name: name.to_string(),
    34	        onboarded_at: onboarded_at.to_string(),
    35	        document,
    36	    };
    37	    store.record_onboarded_issuer(record.clone());
    38	    Ok(record)
    39	}
    40	
    41	#[derive(Debug, Error, PartialEq, Eq)]
    42	pub enum IssueError {
    43	    #[error("holder {0} is not a did:key")]
    44	    InvalidHolder(String),
    45	    #[error("credential would expire before it becomes valid")]
    46	    InvalidValidity,
    47	    #[error("status list {0} is full")]
    48	    StatusListFull(String),
    49	}
    50	
    51	/// What a member asked for.
    52	#[derive(Debug, Clone)]
    53	pub struct CredentialRequest {
    54	    /// The holder's `did:key`.
    55	    pub holder: String,
    56	    /// Added to `type` after `VerifiableCredential`.
    57	    pub credential_type: String,
    58	    pub claims: Vec<(String, Value)>,
    59	    /// Unix seconds.
    60	    pub issued_at: i64,
    61	    /// Unix seconds; defaults to `issued_at`.
    62	    pub not_before: Option<i64>,
    63	    /// Unix seconds.
    64	    pub expires_at: i64,
    65	}
    66	
    67	/// A signed credential plus the disclosures only its holder receives.
    68	#[derive(Debug, Clone)]
    69	pub struct IssuedCredential {
    70	    pub credential: Value,
    71	    pub disclosures: Vec<Disclosure>,
    72	}
    73	
    74	/// An onboarded issuer's signing identity.
    75	pub struct Issuer {
    76	    did: String,
    77	    verification_method: String,
    78	    key: SigningKey,
    79	}
    80	
    81	impl Issuer {
    82	    /// `verification_method` is the DID URL of the key in the issuer's document.
    83	    pub fn new(did: &str, verification_method: &str, seed: &[u8; 32]) -> Self {
    84	        Issuer {
    85	            did: did.to_string(),
    86	            verification_method: verification_method.to_string(),
    87	            key: SigningKey::from_bytes(seed),
    88	        }
    89	    }
    90	
    91	    pub fn did(&self) -> &str {
    92	        &self.did
    93	    }
    94	
    95	    pub fn verifying_key(&self) -> VerifyingKey {
    96	        self.key.verifying_key()
    97	    }
    98	
    99	    /// The status list this issuer's credentials are indexed into.
   100	    pub fn status_list(&self) -> String {
   101	        format!("{}#revocation", self.did)
   102	    }
   103	
   104	    pub fn issue(&self, store: &Store, request: &CredentialRequest) -> Result<IssuedCredential, IssueError> {
   105	        let holder_key = request.holder.strip_prefix("did:key:").unwrap_or_default();
   106	        match affinidi_encoding::decode_multikey_with_codec(holder_key) {
   107	            Ok((affinidi_encoding::ED25519_PUB, _)) => {}
   108	            _ => return Err(IssueError::InvalidHolder(request.holder.clone())),
   109	        }
   110	        let not_before = request.not_before.unwrap_or(request.issued_at);
   111	        if request.expires_at < not_before {
   112	            return Err(IssueError::InvalidValidity);
   113	        }
   114	
   115	        let disclosures: Vec<Disclosure> =
   116	            request.claims.iter().map(|(name, value)| Disclosure::new(name, value.clone())).collect();
   117	        let mut digests: Vec<String> = disclosures.iter().map(Disclosure::digest).collect();
   118	        digests.sort();
   119	
   120	        let status_list = self.status_list();
   121	        let status_index =
   122	            store.allocate_status_index(&status_list).ok_or_else(|| IssueError::StatusListFull(status_list.clone()))?;
   123	
   124	        let id = credential::random_urn();
   125	        let mut vc = json!({
   126	            "@context": [CREDENTIALS_CONTEXT],
   127	            "id": id,
   128	            "type": ["VerifiableCredential", request.credential_type],
   129	            "issuer": self.did,
   130	            "issued_at": request.issued_at,
   131	            "not_before": not_before,
   132	            "expires_at": request.expires_at,
   133	            "credentialSubject": { "id": request.holder, "_sd": digests },
   134	            "credentialStatus": {
   135	                "type": "StatusListEntry",
   136	                "statusListId": status_list,
   137	                "statusListIndex": status_index,
   138	            },
   139	        });
   140	        credential::sign(&mut vc, &self.key, &self.verification_method, "assertionMethod", request.issued_at);
   141	
   142	        store.record_credential(CredentialRecord {
   143	            id,
   144	            issuer: self.did.clone(),
   145	            subject: request.holder.clone(),
   146	            status_list,
   147	            status_index,
   148	            expires_at: request.expires_at,
   149	        });
   150	        Ok(IssuedCredential { credential: vc, disclosures })
   151	    }
   152	}
=== src/lib.rs
     1	//! Issuer and verifier service for membership credentials.
     2	//!
     3	//! - [`issuer`] onboards issuers and signs credentials for their members.
     4	//! - [`verifier`] checks the presentations members show at the door.
     5	//! - [`resolver`] turns a DID into its DID document; [`transport`] fetches
     6	//!   the documents that are hosted rather than encoded in the DID.
     7	//! - [`status`] and [`store`] keep issued credentials and their revocation state.
     8	//! - [`notifier`] tells subscribed relying parties when a status changes;
     9	//!   [`settings`] holds the tenants' subscriptions and [`webhook`] sends the
    10	//!   calls.
    11	//! - [`credential`] is the wire format shared by all of the above.
    12	
    13	pub mod credential;
    14	pub mod issuer;
    15	pub mod notifier;
    16	pub mod resolver;
    17	pub mod settings;
    18	pub mod status;
    19	pub mod store;
    20	pub mod transport;
    21	pub mod verifier;
    22	pub mod webhook;
=== src/notifier.rs
     1	//! Status-change webhooks.
     2	//!
     3	//! When a credential's status flips ([`crate::status::revoke_credential`]),
     4	//! [`Notifier::notify`] sends the change to the relying parties that
     5	//! subscribed to the issuing tenant's changes. A subscription is a tenant
     6	//! setting of kind [`WEBHOOK_KIND`] whose value holds the endpoint `url`.
     7	//!
     8	//! The canary is a platform subscription that receives every change;
     9	//! [`Notifier::canary_healthy`] is the notifier's health check. Every
    10	//! delivery attempt is reported to the [`DeliverySink`].
    11	
    12	use std::sync::atomic::{AtomicBool, Ordering};
    13	use std::sync::{Arc, Mutex};
    14	use std::time::Duration;
    15	
    16	use serde_json::json;
    17	
    18	use crate::settings::{Setting, SettingsStore};
    19	use crate::status::StatusChange;
    20	use crate::webhook::WebhookTransport;
    21	
    22	/// How long one status change may take to fan out.
    23	pub const DISPATCH_BUDGET: Duration = Duration::from_secs(10);
    24	
    25	/// Setting kind of a webhook subscription.
    26	pub const WEBHOOK_KIND: &str = "webhook";
    27	
    28	pub const CANARY_ID: &str = "canary";
    29	pub const CANARY_URL: &str = "https://example.com/webhooks/status";
    30	
    31	#[derive(Debug, Clone, PartialEq, Eq)]
    32	pub struct Subscription {
    33	    pub id: String,
    34	    pub url: String,
    35	}
    36	
    37	impl Subscription {
    38	    pub fn canary() -> Self {
    39	        Subscription { id: CANARY_ID.to_string(), url: CANARY_URL.to_string() }
    40	    }
    41	
    42	    /// The subscription a webhook setting describes; its id is the part of
    43	    /// the key after `webhook/`.
    44	    pub fn from_setting(setting: &Setting) -> Option<Self> {
    45	        let url = setting.value.get("url")?.as_str()?;
    46	        let id = setting.key.strip_prefix("webhook/").unwrap_or(&setting.key);
    47	        Some(Subscription { id: id.to_string(), url: url.to_string() })
    48	    }
    49	}
    50	
    51	#[derive(Debug, Clone, PartialEq, Eq)]
    52	pub enum Outcome {
    53	    /// The endpoint acknowledged the call (2xx).
    54	    Delivered { status: u16 },
    55	    /// The endpoint refused the call or could not be reached.
    56	    Failed { reason: String },
    57	}
    58	
    59	#[derive(Debug, Clone, PartialEq, Eq)]
    60	pub struct DeliveryEvent {
    61	    pub tenant: String,
    62	    pub subscription: String,
    63	    pub outcome: Outcome,
    64	}
    65	
    66	/// Where delivery outcomes go (metrics, audit).
    67	pub trait DeliverySink: Send + Sync {
    68	    fn record(&self, event: DeliveryEvent);
    69	}
    70	
    71	/// Keeps every event in memory.
    72	#[derive(Debug, Default)]
    73	pub struct MemorySink {
    74	    events: Mutex<Vec<DeliveryEvent>>,
    75	}
    76	
    77	impl MemorySink {
    78	    pub fn events(&self) -> Vec<DeliveryEvent> {
    79	        self.events.lock().unwrap().clone()
    80	    }
    81	}
    82	
    83	impl DeliverySink for MemorySink {
    84	    fn record(&self, event: DeliveryEvent) {
    85	        self.events.lock().unwrap().push(event);
    86	    }
    87	}
    88	
    89	/// The JSON body sent for `change`.
    90	pub fn payload(change: &StatusChange) -> Vec<u8> {
    91	    json!({
    92	        "type": "credential.status_changed",
    93	        "credential_id": change.credential_id,
    94	        "issuer": change.issuer,
    95	        "status_list": change.status_list,
    96	        "status_index": change.status_index,
    97	        "revoked": change.revoked,
    98	    })
    99	    .to_string()
   100	    .into_bytes()
   101	}
   102	
   103	pub struct Notifier {
   104	    settings: Arc<SettingsStore>,
   105	    transport: Arc<dyn WebhookTransport>,
   106	    sink: Arc<dyn DeliverySink>,
   107	    /// Subscribers to every tenant's changes.
   108	    platform: Vec<Subscription>,
   109	    canary_ok: AtomicBool,
   110	}
   111	
   112	impl Notifier {
   113	    pub fn new(settings: Arc<SettingsStore>, transport: Arc<dyn WebhookTransport>, sink: Arc<dyn DeliverySink>) -> Self {
   114	        Notifier {
   115	            settings,
   116	            transport,
   117	            sink,
   118	            platform: vec![Subscription::canary()],
   119	            canary_ok: AtomicBool::new(false),
   120	        }
   121	    }
   122	
   123	    /// Adds a subscriber to every tenant's changes.
   124	    pub fn with_platform_subscriber(mut self, subscription: Subscription) -> Self {
   125	        self.platform.push(subscription);
   126	        self
   127	    }
   128	
   129	    /// Whether the canary acknowledged the most recent change.
   130	    pub fn canary_healthy(&self) -> bool {
   131	        self.canary_ok.load(Ordering::SeqCst)
   132	    }
   133	
   134	    /// Sends `change` to the platform subscribers and to every subscriber of
   135	    /// the issuing tenant.
   136	    pub async fn notify(&self, change: &StatusChange) {
   137	        let tenant = change.issuer.as_str();
   138	        let body = payload(change);
   139	
   140	        let fan_out = async {
   141	            for sub in &self.platform {
   142	                let delivered = self.dispatch(tenant, sub, &body).await;
   143	                if sub.id == CANARY_ID {
   144	                    self.canary_ok.store(delivered, Ordering::SeqCst);
   145	                }
   146	            }
   147	            for sub in self.subscriptions(tenant).await {
   148	                self.dispatch(tenant, &sub, &body).await;
   149	            }
   150	        };
   151	
   152	        if tokio::time::timeout(DISPATCH_BUDGET, fan_out).await.is_err() {
   153	            eprintln!("notifier: {tenant}: fan-out for {} did not finish within {DISPATCH_BUDGET:?}", change.credential_id);
   154	        }
   155	    }
   156	
   157	    /// The tenant's webhook subscriptions.
   158	    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
   159	        let mut subscriptions = Vec::new();
   160	        let mut cursor: Option<String> = None;
   161	        loop {
   162	            let page = self.settings.query(tenant, cursor.as_deref()).await;
   163	            subscriptions.extend(page.items.iter().filter(|s| s.kind == WEBHOOK_KIND).filter_map(Subscription::from_setting));
   164	            match page.next {
   165	                Some(next) => cursor = Some(next),
   166	                None => return subscriptions,
   167	            }
   168	        }
   169	    }
   170	
   171	    /// POSTs `body` to `sub` and reports the outcome; `true` if delivered.
   172	    async fn dispatch(&self, tenant: &str, sub: &Subscription, body: &[u8]) -> bool {
   173	        let outcome = match self.transport.post(&sub.url, body).await {
   174	            Ok(status) if (200..300).contains(&status) => Outcome::Delivered { status },
   175	            Ok(status) => Outcome::Failed { reason: format!("HTTP {status}") },
   176	            Err(error) => Outcome::Failed { reason: error.to_string() },
   177	        };
   178	        let delivered = matches!(outcome, Outcome::Delivered { .. });
   179	        self.sink.record(DeliveryEvent { tenant: tenant.to_string(), subscription: sub.id.clone(), outcome });
   180	        delivered
   181	    }
   182	}
