2	     1	//! The credential wire format: canonical JSON, Ed25519 proofs and
3	     2	//! selectively disclosable claims.
4	     3	//!
5	     4	//! Every signature in the system covers the RFC 8785 (JCS) form of a document
6	     5	//! with its `proof` member removed, so a document signed by the wallet and
7	     6	//! verified here (or the other way round) hashes the same bytes on both sides.
8	     7	
9	     8	use base64::engine::general_purpose::URL_SAFE_NO_PAD;
10	     9	use base64::Engine;
11	    10	use ed25519_dalek::{Signature, Signer, SigningKey, Verifier as _, VerifyingKey};
12	    11	use serde::{Deserialize, Serialize};
13	    12	use serde_json::{json, Value};
14	    13	use sha2::{Digest, Sha256};
15	    14	
16	    15	pub const ED25519_SIGNATURE_2020: &str = "Ed25519Signature2020";
17	    16	pub const CREDENTIALS_CONTEXT: &str = "https://www.w3.org/2018/credentials/v1";
18	    17	
19	    18	/// One selectively disclosable claim, as handed to the holder at issuance.
20	    19	///
21	    20	/// The credential itself only carries [`Disclosure::digest`] in
22	    21	/// `credentialSubject._sd`; the holder reveals a claim by presenting its
23	    22	/// disclosure next to the credential.
24	    23	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
25	    24	pub struct Disclosure {
26	    25	    pub salt: String,
27	    26	    pub name: String,
28	    27	    pub value: Value,
29	    28	}
30	    29	
31	    30	impl Disclosure {
32	    31	    pub fn new(name: &str, value: Value) -> Self {
33	    32	        Disclosure { salt: random_token(16), name: name.to_string(), value }
34	    33	    }
35	    34	
36	    35	    /// base64url (no padding) of SHA-256 over the canonical `[salt, name, value]` array.
37	    36	    pub fn digest(&self) -> String {
38	    37	        let triple = json!([self.salt, self.name, self.value]);
39	    38	        URL_SAFE_NO_PAD.encode(Sha256::digest(canonicalize(&triple).as_bytes()))
40	    39	    }
41	    40	}
42	    41	
43	    42	/// The bytes a proof signs: the canonical form of `document` without `proof`.
44	    43	pub fn signing_input(document: &Value) -> Vec<u8> {
45	    44	    match document {
46	    45	        Value::Object(map) if map.contains_key("proof") => {
47	    46	            let mut unsigned = map.clone();
48	    47	            unsigned.remove("proof");
49	    48	            canonicalize(&Value::Object(unsigned)).into_bytes()
50	    49	        }
51	    50	        other => canonicalize(other).into_bytes(),
52	    51	    }
53	    52	}
54	    53	
55	    54	/// Adds (or replaces) an `Ed25519Signature2020` proof on `document`.
56	    55	pub fn sign(document: &mut Value, key: &SigningKey, verification_method: &str, purpose: &str, created: i64) {
57	    56	    let signature = key.sign(&signing_input(document));
58	    57	    document["proof"] = json!({
59	    58	        "type": ED25519_SIGNATURE_2020,
60	    59	        "created": created,
61	    60	        "verificationMethod": verification_method,
62	    61	        "proofPurpose": purpose,
63	    62	        "proofValue": affinidi_encoding::encode_base58btc(&signature.to_bytes()),
64	    63	    });
65	    64	}
66	    65	
67	    66	/// Checks the `proofValue` of `document` against `key`.
68	    67	pub fn verify_signature(document: &Value, key: &VerifyingKey) -> Result<(), String> {
69	    68	    let proof_value = document
70	    69	        .pointer("/proof/proofValue")
71	    70	        .and_then(Value::as_str)
72	    71	        .ok_or("proof has no proofValue")?;
73	    72	    let bytes = affinidi_encoding::decode_base58btc(proof_value).map_err(|e| format!("proofValue: {e}"))?;
74	    73	    let signature = Signature::from_slice(&bytes).map_err(|e| format!("proofValue: {e}"))?;
75	    74	    key.verify(&signing_input(document), &signature).map_err(|_| "signature does not match".to_string())
76	    75	}
77	    76	
78	    77	/// RFC 8785 JSON Canonicalization Scheme.
79	    78	///
80	    79	/// Object members are ordered by the UTF-16 code units of their names,
81	    80	/// strings use the minimal JSON escaping, and numbers are written the way
82	    81	/// ECMAScript prints them (integral values without a fraction).
83	    82	pub fn canonicalize(value: &Value) -> String {
84	    83	    let mut out = String::new();
85	    84	    write_canonical(value, &mut out);
86	    85	    out
87	    86	}
88	    87	
89	    88	fn write_canonical(value: &Value, out: &mut String) {
90	    89	    match value {
91	    90	        Value::Null | Value::Bool(_) | Value::String(_) => {
92	    91	            out.push_str(&serde_json::to_string(value).expect("scalars serialize"))
93	    92	        }
94	    93	        Value::Number(n) => out.push_str(&canonical_number(n)),
95	    94	        Value::Array(items) => {
96	    95	            out.push('[');
97	    96	            for (i, item) in items.iter().enumerate() {
98	    97	                if i > 0 {
99	    98	                    out.push(',');
100	    99	                }
101	   100	                write_canonical(item, out);
102	   101	            }
103	   102	            out.push(']');
104	   103	        }
105	   104	        Value::Object(map) => {
106	   105	            let mut entries: Vec<(&String, &Value)> = map.iter().collect();
107	   106	            entries.sort_by(|(a, _), (b, _)| a.encode_utf16().cmp(b.encode_utf16()));
108	   107	            out.push('{');
109	   108	            for (i, (key, item)) in entries.into_iter().enumerate() {
110	   109	                if i > 0 {
111	   110	                    out.push(',');
112	   111	                }
113	   112	                out.push_str(&serde_json::to_string(key).expect("keys serialize"));
114	   113	                out.push(':');
115	   114	                write_canonical(item, out);
116	   115	            }
117	   116	            out.push('}');
118	   117	        }
119	   118	    }
120	   119	}
121	   120	
122	   121	fn canonical_number(n: &serde_json::Number) -> String {
123	   122	    if n.is_i64() || n.is_u64() {
124	   123	        return n.to_string();
125	   124	    }
126	   125	    let f = n.as_f64().unwrap_or(0.0);
127	   126	    if f == f.trunc() && f.abs() < 1e21 {
128	   127	        format!("{}", f as i128)
129	   128	    } else {
130	   129	        format!("{f}")
131	   130	    }
132	   131	}
133	   132	
134	   133	/// A random base64url token of `bytes` bytes of entropy.
135	   134	pub fn random_token(bytes: usize) -> String {
136	   135	    let mut buf = vec![0u8; bytes];
137	   136	    getrandom::fill(&mut buf).expect("system randomness");
138	   137	    URL_SAFE_NO_PAD.encode(buf)
139	   138	}
140	   139	
141	   140	/// A random (version 4) `urn:uuid:` identifier.
142	   141	pub fn random_urn() -> String {
143	   142	    let mut b = [0u8; 16];
144	   143	    getrandom::fill(&mut b).expect("system randomness");
145	   144	    b[6] = (b[6] & 0x0f) | 0x40;
146	   145	    b[8] = (b[8] & 0x3f) | 0x80;
147	   146	    let hex: String = b.iter().map(|x| format!("{x:02x}")).collect();
148	   147	    format!("urn:uuid:{}-{}-{}-{}-{}", &hex[0..8], &hex[8..12], &hex[12..16], &hex[16..20], &hex[20..32])
149	   148	}
