535	    26	    InvalidDid(String),
536	    27	    #[error("unsupported DID method {0}")]
537	    28	    UnsupportedMethod(String),
538	    29	    #[error(transparent)]
539	    30	    Transport(#[from] TransportError),
540	    31	    #[error("document for {did} is not a valid DID document: {reason}")]
541	    32	    InvalidDocument { did: String, reason: String },
542	    33	    #[error("document fetched for {did} is for {found}")]
543	    34	    DocumentMismatch { did: String, found: String },
544	    35	}
