587	    78	/// The HTTPS URL a `did:web` document is published at: `did.json` under the
588	    79	/// host's `/.well-known/` directory, with any further segments of the
589	    80	/// identifier as subdirectories. A port is written percent-encoded in the host
590	    81	/// segment (`example.com%3A8443`).
591	    82	pub fn did_web_url(did: &str) -> Result<String, ResolveError> {
592	    83	    let invalid = || ResolveError::InvalidDid(did.to_string());
593	    84	    let id = did.strip_prefix("did:web:").ok_or_else(invalid)?;
594	    85	    let mut segments = id.split(':');
595	    86	    let host = percent_decode(segments.next().unwrap_or_default()).ok_or_else(invalid)?;
596	    87	    if host.is_empty() || host.contains('/') {
597	    88	        return Err(invalid());
598	    89	    }
599	    90	    let path: Vec<String> = segments.map(percent_decode).collect::<Option<_>>().ok_or_else(invalid)?;
600	    91	    if path.iter().any(|s| s.is_empty() || s.contains('/')) {
601	    92	        return Err(invalid());
602	    93	    }
603	    94	    let mut url = format!("https://{host}/.well-known");
604	    95	    for segment in &path {
605	    96	        url.push('/');
606	    97	        url.push_str(segment);
607	    98	    }
608	    99	    url.push_str("/did.json");
609	   100	    Ok(url)
610	   101	}
611	   102	
612	   103	fn percent_decode(segment: &str) -> Option<String> {
613	   104	    let bytes = segment.as_bytes();
614	   105	    let mut out = Vec::with_capacity(bytes.len());
615	   106	    let mut i = 0;
616	   107	    while i < bytes.len() {
617	   108	        if bytes[i] == b'%' {
618	   109	            let hex = std::str::from_utf8(bytes.get(i + 1..i + 3)?).ok()?;
619	   110	            out.push(u8::from_str_radix(hex, 16).ok()?);
620	   111	            i += 3;
621	   112	        } else {
622	   113	            out.push(bytes[i]);
623	   114	            i += 1;
624	   115	        }
625	   116	    }
626	   117	    String::from_utf8(out).ok()
627	   118	}
