634	   125	fn resolve_peer(did: &str) -> Result<Document, ResolveError> {
635	   126	    let id = did.strip_prefix("did:peer:").unwrap_or_default();
636	   127	    if let Some(multibase) = id.strip_prefix('0') {
637	   128	        single_key_document(did, multibase)
638	   129	    } else if let Some(elements) = id.strip_prefix("2.") {
639	   130	        peer_2_document(did, elements)
