645	   136	/// Checks that `multibase` is an Ed25519 multikey.
646	   137	fn ed25519_multikey(did: &str, multibase: &str) -> Result<(), ResolveError> {
647	   138	    match affinidi_encoding::decode_multikey_with_codec(multibase) {
648	   139	        Ok((affinidi_encoding::ED25519_PUB, bytes)) if bytes.len() == 32 => Ok(()),
649	   140	        _ => Err(ResolveError::InvalidDid(did.to_string())),
650	   141	    }
651	   142	}
