657	   148	fn single_key_document(did: &str, multibase: &str) -> Result<Document, ResolveError> {
658	   149	    ed25519_multikey(did, multibase)?;
659	   150	    let vm_id = format!("{did}#{multibase}");
660	   151	    to_document(did, json!({
661	   152	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
662	   153	        "id": did,
663	   154	        "verificationMethod": [multikey(&vm_id, did, multibase)],
664	   155	        "authentication": [vm_id],
665	   156	        "assertionMethod": [vm_id],
666	   157	        "capabilityInvocation": [vm_id],
667	   158	        "capabilityDelegation": [vm_id],
668	   159	    }))
669	   160	}
