671	   162	fn peer_2_document(did: &str, elements: &str) -> Result<Document, ResolveError> {
672	   163	    let invalid = || ResolveError::InvalidDid(did.to_string());
673	   164	    let mut methods = Vec::new();
674	   165	    let mut relationships: Map<String, Value> = Map::new();
675	   166	    let mut services = Vec::new();
676	   167	
677	   168	    for element in elements.split('.') {
678	   169	        let mut chars = element.chars();
679	   170	        let purpose = chars.next().ok_or_else(invalid)?;
680	   171	        let body = chars.as_str();
681	   172	        let relationship = match purpose {
682	   173	            'A' => "assertionMethod",
683	   174	            'V' => "authentication",
684	   175	            'E' => "keyAgreement",
685	   176	            'I' => "capabilityInvocation",
686	   177	            'D' => "capabilityDelegation",
687	   178	            'S' => {
688	   179	                let raw = URL_SAFE_NO_PAD.decode(body.trim_end_matches('=')).map_err(|_| invalid())?;
689	   180	                let abbreviated: Value = serde_json::from_slice(&raw).map_err(|_| invalid())?;
690	   181	                let id = match services.len() {
691	   182	                    0 => format!("{did}#service"),
692	   183	                    n => format!("{did}#service-{n}"),
693	   184	                };
694	   185	                let mut service = expand_service(&abbreviated);
695	   186	                service["id"] = json!(id);
696	   187	                services.push(service);
697	   188	                continue;
698	   189	            }
699	   190	            _ => return Err(invalid()),
700	   191	        };
701	   192	        if purpose != 'E' {
702	   193	            ed25519_multikey(did, body)?;
703	   194	        }
704	   195	        let vm_id = format!("{did}#key-{}", methods.len() + 1);
705	   196	        methods.push(multikey(&vm_id, did, body));
706	   197	        relationships.entry(relationship).or_insert_with(|| json!([])).as_array_mut().unwrap().push(json!(vm_id));
707	   198	    }
708	   199	
709	   200	    let mut document = json!({
710	   201	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
711	   202	        "id": did,
712	   203	        "verificationMethod": methods,
713	   204	        "service": services,
714	   205	    });
715	   206	    for (relationship, ids) in relationships {
716	   207	        document[relationship] = ids;
717	   208	    }
718	   209	    to_document(did, document)
719	   210	}
