721	   212	/// Expands the abbreviated keys peer:2 uses for services (`t`, `s`, `r`, `a`, `dm`).
722	   213	fn expand_service(value: &Value) -> Value {
723	   214	    match value {
724	   215	        Value::Object(map) => Value::Object(
725	   216	            map.iter()
726	   217	                .map(|(k, v)| {
727	   218	                    let key = match k.as_str() {
728	   219	                        "t" => "type",
729	   220	                        "s" => "serviceEndpoint",
730	   221	                        "r" => "routingKeys",
731	   222	                        "a" => "accept",
732	   223	                        other => other,
733	   224	                    };
734	   225	                    (key.to_string(), expand_service(v))
735	   226	                })
736	   227	                .collect(),
737	   228	        ),
738	   229	        Value::String(s) if s == "dm" => json!("DIDCommMessaging"),
739	   230	        Value::Array(items) => Value::Array(items.iter().map(expand_service).collect()),
740	   231	        other => other.clone(),
741	   232	    }
742	   233	}
