   103	pub struct Notifier {
   104	    settings: Arc<SettingsStore>,
   105	    transport: Arc<dyn WebhookTransport>,
   106	    sink: Arc<dyn DeliverySink>,
   107	    /// Subscribers to every tenant's changes.
   108	    platform: Vec<Subscription>,
   109	    canary_ok: AtomicBool,
   110	}
   111	
   112	impl Notifier {
   113	    pub fn new(settings: Arc<SettingsStore>, transport: Arc<dyn WebhookTransport>, sink: Arc<dyn DeliverySink>) -> Self {
   114	        Notifier {
   115	            settings,
   116	            transport,
   117	            sink,
   118	            platform: vec![Subscription::canary()],
   119	            canary_ok: AtomicBool::new(false),
   120	        }
   121	    }
   122	
   123	    /// Adds a subscriber to every tenant's changes.
   124	    pub fn with_platform_subscriber(mut self, subscription: Subscription) -> Self {
   125	        self.platform.push(subscription);
   126	        self
   127	    }
   128	
   129	    /// Whether the canary acknowledged the most recent change.
   130	    pub fn canary_healthy(&self) -> bool {
   131	        self.canary_ok.load(Ordering::SeqCst)
   132	    }
   133	
   134	    /// Sends `change` to the platform subscribers and to every subscriber of
   135	    /// the issuing tenant.
   136	    pub async fn notify(&self, change: &StatusChange) {
   137	        let tenant = change.issuer.as_str();
   138	        let body = payload(change);
   139	
   140	        let fan_out = async {
   141	            for sub in &self.platform {
   142	                let delivered = self.dispatch(tenant, sub, &body).await;
   143	                if sub.id == CANARY_ID {
   144	                    self.canary_ok.store(delivered, Ordering::SeqCst);
   145	                }
   146	            }
   147	            for sub in self.subscriptions(tenant).await {
   148	                self.dispatch(tenant, &sub, &body).await;
   149	            }
   150	        };
   151	
   152	        if tokio::time::timeout(DISPATCH_BUDGET, fan_out).await.is_err() {
   153	            eprintln!("notifier: {tenant}: fan-out for {} did not finish within {DISPATCH_BUDGET:?}", change.credential_id);
   154	        }
   155	    }
   156	
   157	    /// The tenant's webhook subscriptions.
   158	    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
   159	        let mut subscriptions = Vec::new();
   160	        let mut cursor: Option<String> = None;
   161	        loop {
   162	            let page = self.settings.query(tenant, cursor.as_deref()).await;
   163	            subscriptions.extend(page.items.iter().filter(|s| s.kind == WEBHOOK_KIND).filter_map(Subscription::from_setting));
   164	            match page.next {
   165	                Some(next) => cursor = Some(next),
   166	                None => return subscriptions,
   167	            }
   168	        }
   169	    }
   170	
   171	    /// POSTs `body` to `sub` and reports the outcome; `true` if delivered.
   172	    async fn dispatch(&self, tenant: &str, sub: &Subscription, body: &[u8]) -> bool {
   173	        let outcome = match self.transport.post(&sub.url, body).await {
   174	            Ok(status) if (200..300).contains(&status) => Outcome::Delivered { status },
   175	            Ok(status) => Outcome::Failed { reason: format!("HTTP {status}") },
   176	            Err(error) => Outcome::Failed { reason: error.to_string() },
   177	        };
   178	        let delivered = matches!(outcome, Outcome::Delivered { .. });
   179	        self.sink.record(DeliveryEvent { tenant: tenant.to_string(), subscription: sub.id.clone(), outcome });
   180	        delivered
   181	    }
   182	}
