     1	//! Tenant settings: the in-repo stand-in for the `tenant-settings` table.
     2	//!
     3	//! Every tenant (an onboarded issuer, keyed by its DID) owns a partition of
     4	//! settings, each identified by a key and tagged with a kind. Like the table,
     5	//! a query returns a partition one page at a time in key order, and every
     6	//! page read takes [`PAGE_READ_LATENCY`]. The `tenant-kind` index answers
     7	//! "settings of this kind for this tenant" directly.
     8	
     9	use std::collections::{BTreeMap, BTreeSet};
    10	use std::ops::Bound;
    11	use std::sync::Mutex;
    12	use std::time::Duration;
    13	
    14	use serde_json::Value;
    15	
    16	/// Items returned per page read.
    17	pub const PAGE_SIZE: usize = 100;
    18	
    19	/// What one page read costs.
    20	pub const PAGE_READ_LATENCY: Duration = Duration::from_millis(50);
    21	
    22	#[derive(Debug, Clone, PartialEq)]
    23	pub struct Setting {
    24	    pub tenant: String,
    25	    pub key: String,
    26	    pub kind: String,
    27	    pub value: Value,
    28	}
    29	
    30	impl Setting {
    31	    pub fn new(tenant: &str, key: &str, kind: &str, value: Value) -> Self {
    32	        Setting { tenant: tenant.to_string(), key: key.to_string(), kind: kind.to_string(), value }
    33	    }
    34	}
    35	
    36	/// One page of a partition. `next` is the cursor for the following page,
    37	/// `None` on the last one.
    38	#[derive(Debug, Clone, PartialEq)]
    39	pub struct Page {
    40	    pub items: Vec<Setting>,
    41	    pub next: Option<String>,
    42	}
    43	
    44	#[derive(Default)]
    45	struct Inner {
    46	    /// tenant → key → setting
    47	    partitions: BTreeMap<String, BTreeMap<String, Setting>>,
    48	    /// (tenant, kind) → keys
    49	    by_kind: BTreeMap<(String, String), BTreeSet<String>>,
    50	}
    51	
    52	#[derive(Default)]
    53	pub struct SettingsStore {
    54	    inner: Mutex<Inner>,
    55	}
    56	
    57	impl SettingsStore {
    58	    pub fn new() -> Self {
    59	        SettingsStore::default()
    60	    }
    61	
    62	    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
    63	        self.inner.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    64	    }
    65	
    66	    /// Writes `setting`, replacing any setting with the same tenant and key.
    67	    pub fn put(&self, setting: Setting) {
    68	        let mut inner = self.lock();
    69	        let partition = inner.partitions.entry(setting.tenant.clone()).or_default();
    70	        let previous = partition.insert(setting.key.clone(), setting.clone());
    71	        if let Some(previous) = previous {
    72	            if let Some(keys) = inner.by_kind.get_mut(&(previous.tenant, previous.kind)) {
    73	                keys.remove(&previous.key);
    74	            }
    75	        }
    76	        inner.by_kind.entry((setting.tenant, setting.kind)).or_default().insert(setting.key);
    77	    }
    78	
    79	    /// One page of `tenant`'s settings, starting after the key `after`.
    80	    pub async fn query(&self, tenant: &str, after: Option<&str>) -> Page {
    81	        tokio::time::sleep(PAGE_READ_LATENCY).await;
    82	        let inner = self.lock();
    83	        let Some(partition) = inner.partitions.get(tenant) else {
    84	            return Page { items: Vec::new(), next: None };
    85	        };
    86	        let start = match after {
    87	            Some(key) => Bound::Excluded(key.to_string()),
    88	            None => Bound::Unbounded,
    89	        };
    90	        let mut range = partition.range((start, Bound::Unbounded));
    91	        let items: Vec<Setting> = range.by_ref().take(PAGE_SIZE).map(|(_, s)| s.clone()).collect();
    92	        let next = match range.next() {
    93	            Some(_) => items.last().map(|s| s.key.clone()),
    94	            None => None,
    95	        };
    96	        Page { items, next }
    97	    }
    98	
    99	    /// `tenant`'s settings of `kind`, through the `tenant-kind` index.
   100	    pub async fn query_kind(&self, tenant: &str, kind: &str) -> Vec<Setting> {
   101	        let items: Vec<Setting> = {
   102	            let inner = self.lock();
   103	            let keys = inner.by_kind.get(&(tenant.to_string(), kind.to_string()));
   104	            let partition = inner.partitions.get(tenant);
   105	            match (keys, partition) {
   106	                (Some(keys), Some(partition)) => keys.iter().filter_map(|k| partition.get(k).cloned()).collect(),
   107	                _ => Vec::new(),
   108	            }
   109	        };
   110	        let pages = items.len().div_ceil(PAGE_SIZE).max(1) as u32;
   111	        tokio::time::sleep(PAGE_READ_LATENCY * pages).await;
   112	        items
   113	    }
   114	}
