     1	//! Revocation through status lists.
     2	//!
     3	//! Each issuer publishes one bitstring. Every credential it issues carries an
     4	//! index into that bitstring (`credentialStatus.statusListIndex`); the
     5	//! credential is revoked when the bit at that index is 1. Bit 0 is the
     6	//! most significant bit of the first byte.
     7	
     8	use base64::engine::general_purpose::URL_SAFE_NO_PAD;
     9	use base64::Engine;
    10	use thiserror::Error;
    11	
    12	use crate::store::Store;
    13	
    14	/// Bits per list: large enough that an index says little about when a
    15	/// credential was issued.
    16	pub const DEFAULT_CAPACITY: usize = 131_072;
    17	
    18	#[derive(Debug, Clone, PartialEq, Eq)]
    19	pub struct StatusList {
    20	    bits: Vec<u8>,
    21	    capacity: usize,
    22	    allocated: usize,
    23	}
    24	
    25	impl StatusList {
    26	    pub fn new(capacity: usize) -> Self {
    27	        StatusList { bits: vec![0; capacity.div_ceil(8)], capacity, allocated: 0 }
    28	    }
    29	
    30	    pub fn capacity(&self) -> usize {
    31	        self.capacity
    32	    }
    33	
    34	    /// Reserves the next unused index, or `None` once the list is full.
    35	    pub fn allocate(&mut self) -> Option<usize> {
    36	        if self.allocated >= self.capacity {
    37	            return None;
    38	        }
    39	        self.allocated += 1;
    40	        Some(self.allocated)
    41	    }
    42	
    43	    pub fn set(&mut self, index: usize, revoked: bool) {
    44	        let mask = 0x80u8 >> (index % 8);
    45	        if let Some(byte) = self.bits.get_mut(index / 8) {
    46	            if revoked {
    47	                *byte |= mask;
    48	            } else {
    49	                *byte &= !mask;
    50	            }
    51	        }
    52	    }
    53	
    54	    pub fn is_set(&self, index: usize) -> bool {
    55	        let mask = 0x80u8 >> (index % 8);
    56	        self.bits.get(index / 8).is_some_and(|byte| byte & mask != 0)
    57	    }
    58	
    59	    /// The published form of the list: base64url of the bitstring.
    60	    pub fn encode(&self) -> String {
    61	        URL_SAFE_NO_PAD.encode(&self.bits)
    62	    }
    63	
    64	    pub fn decode(encoded: &str, capacity: usize) -> Option<Self> {
    65	        let bits = URL_SAFE_NO_PAD.decode(encoded).ok()?;
    66	        (bits.len() == capacity.div_ceil(8)).then_some(StatusList { bits, capacity, allocated: capacity })
    67	    }
    68	}
    69	
    70	#[derive(Debug, Error, PartialEq, Eq)]
    71	pub enum StatusError {
    72	    #[error("no credential {0}")]
    73	    UnknownCredential(String),
    74	    #[error("no status list {0}")]
    75	    UnknownList(String),
    76	}
    77	
    78	/// What changed when a credential's status flipped.
    79	#[derive(Debug, Clone, PartialEq, Eq)]
    80	pub struct StatusChange {
    81	    pub credential_id: String,
    82	    pub issuer: String,
    83	    pub status_list: String,
    84	    pub status_index: usize,
    85	    pub revoked: bool,
    86	}
    87	
    88	/// Revokes an issued credential by setting its bit in its issuer's list.
    89	pub fn revoke_credential(store: &Store, credential_id: &str) -> Result<StatusChange, StatusError> {
    90	    let record = store
    91	        .credential(credential_id)
    92	        .ok_or_else(|| StatusError::UnknownCredential(credential_id.to_string()))?;
    93	    if !store.set_status(&record.status_list, record.status_index, true) {
    94	        return Err(StatusError::UnknownList(record.status_list));
    95	    }
    96	    Ok(StatusChange {
    97	        credential_id: record.id,
    98	        issuer: record.issuer,
    99	        status_list: record.status_list,
   100	        status_index: record.status_index,
   101	        revoked: true,
   102	    })
   103	}
