    29	    pub status_index: usize,
    30	    pub expires_at: i64,
    31	}
    32	
    33	#[derive(Default)]
    34	struct Inner {
    35	    issuers: HashMap<String, OnboardedIssuer>,
    36	    credentials: HashMap<String, CredentialRecord>,
    37	    status_lists: HashMap<String, StatusList>,
    38	}
    39	
    40	#[derive(Default)]
    41	pub struct Store {
    42	    inner: Mutex<Inner>,
    43	}
    44	
    45	impl Store {
    46	    pub fn new() -> Self {
    47	        Store::default()
    48	    }
    49	
    50	    /// A store holding every issuer in `data/onboarded-issuers.json`.
    51	    pub fn from_onboarding_data() -> Result<Self, serde_json::Error> {
    52	        let issuers: Vec<OnboardedIssuer> = serde_json::from_str(ONBOARDING_DATA)?;
    53	        let store = Store::new();
    54	        for issuer in issuers {
    55	            store.record_onboarded_issuer(issuer);
    56	        }
