    59	
    60	    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
    61	        self.inner.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    62	    }
    63	
    64	    pub fn record_onboarded_issuer(&self, issuer: OnboardedIssuer) {
    65	        self.lock().issuers.insert(issuer.did.clone(), issuer);
    66	    }
