    68	    /// Issuer documents are self-contained, as with the peer DIDs issuers
    69	    /// first onboarded with: keys and service endpoints travel with the
    70	    /// document, so the copy recorded at onboarding is all verification needs.
    71	    pub fn onboarded_issuer(&self, did: &str) -> Option<OnboardedIssuer> {
    72	        self.lock().issuers.get(did).cloned()
    73	    }
