    86	        self.lock().credentials.get(id).cloned()
    87	    }
    88	
    89	    /// Reserves an index in `list`, creating the list on first use.
    90	    pub fn allocate_status_index(&self, list: &str) -> Option<usize> {
    91	        self.lock()
    92	            .status_lists
    93	            .entry(list.to_string())
    94	            .or_insert_with(|| StatusList::new(DEFAULT_CAPACITY))
    95	            .allocate()
    96	    }
    97	
    98	    /// Sets the bit at `index` in `list`; `false` if there is no such list.
    99	    pub fn set_status(&self, list: &str, index: usize, revoked: bool) -> bool {
   100	        match self.lock().status_lists.get_mut(list) {
   101	            Some(status) => {
   102	                status.set(index, revoked);
   103	                true
   104	            }
   105	            None => false,
   106	        }
   107	    }
   108	
   109	    pub fn is_revoked(&self, list: &str, index: usize) -> Option<bool> {
   110	        self.lock().status_lists.get(list).map(|status| status.is_set(index))
   111	    }
   112	
   113	    /// The published form of `list`.
   114	    pub fn encoded_status_list(&self, list: &str) -> Option<String> {
   115	        self.lock().status_lists.get(list).map(StatusList::encode)
   116	    }
   117	}
