   122	        match self.resolver.resolve(holder) {
   123	            Ok(document) => check_proof(vp, &document, &document.authentication)?,
   124	            Err(ResolveError::UnsupportedMethod(_)) => {}
   125	            Err(e) => return Err(e.into()),
   126	        }
   127	
   128	        let vc = vp.get("verifiableCredential").ok_or_else(|| malformed("verifiableCredential"))?;
   129	        let credential = self.verify_credential(vc)?;
   130	        if credential.subject != holder {
   131	            return Err(VerifyError::HolderMismatch);
   132	        }
   133	
   134	        let committed: HashSet<&str> = vc
   135	            .pointer("/credentialSubject/_sd")
   136	            .and_then(Value::as_array)
   137	            .map(|digests| digests.iter().filter_map(Value::as_str).collect())
   138	            .unwrap_or_default();
   139	        let disclosures: Vec<Disclosure> = match vp.get("disclosures") {
   140	            Some(list) => serde_json::from_value(list.clone()).map_err(|_| malformed("disclosures"))?,
   141	            None => Vec::new(),
   142	        };
   143	        let mut claims = BTreeMap::new();
   144	        for disclosure in disclosures {
   145	            if !committed.contains(disclosure.digest().as_str()) {
   146	                return Err(VerifyError::UndisclosedClaim(disclosure.name));
   147	            }
   148	            claims.insert(disclosure.name, disclosure.value);
   149	        }
   150	
   151	        Ok(VerifiedPresentation { holder: holder.to_string(), credential, claims })
   152	    }
   153	
   154	    /// Verifies a credential: issuer proof, validity window and status.
   155	    pub fn verify_credential(&self, vc: &Value) -> Result<VerifiedCredential, VerifyError> {
   156	        let issuer = str_field(vc, "issuer")?;
   157	        let subject = vc.pointer("/credentialSubject/id").and_then(Value::as_str).ok_or_else(|| malformed("credentialSubject.id"))?;
   158	        let id = str_field(vc, "id")?;
   159	
   160	        let document = self.resolve_issuer(issuer)?;
   161	        check_proof(vc, &document, &document.assertion_method)?;
   162	
   163	        let now = (self.clock)();
   164	        let not_before = int_field(vc, "not_before")?;
   165	        let expires_at = int_field(vc, "expires_at")?;
   166	        if now < not_before {
   167	            return Err(VerifyError::NotYetValid);
   168	        }
   169	        if now > expires_at {
   170	            return Err(VerifyError::Expired);
   171	        }
   172	
   173	        let list = vc.pointer("/credentialStatus/statusListId").and_then(Value::as_str).ok_or_else(|| malformed("credentialStatus"))?;
   174	        let index = vc.pointer("/credentialStatus/statusListIndex").and_then(Value::as_u64).ok_or_else(|| malformed("credentialStatus"))?;
   175	        match self.store.is_revoked(list, index as usize) {
   176	            Some(false) => {}
   177	            Some(true) => return Err(VerifyError::Revoked),
   178	            None => return Err(VerifyError::UnknownStatus(list.to_string())),
   179	        }
   180	
   181	        let issuer_site = document
   182	            .service
   183	            .iter()
   184	            .find(|service| service.type_.iter().any(|t| t == "LinkedDomains"))
   185	            .and_then(|service| service.service_endpoint.get_uri());
   186	
   187	        Ok(VerifiedCredential {
   188	            id: id.to_string(),
   189	            issuer: issuer.to_string(),
   190	            subject: subject.to_string(),
   191	            expires_at,
   192	            issuer_site,
   193	        })
   194	    }
   195	
   196	    /// The DID document an issuer's credentials are checked against.
   197	    pub fn resolve_issuer(&self, did: &str) -> Result<Document, VerifyError> {
   198	        if let Some(issuer) = self.store.onboarded_issuer(did) {
   199	            return Ok(issuer.document);
   200	        }
   201	        Ok(self.resolver.resolve(did)?)
   202	    }
   203	}
   204	
   205	/// Checks `document`'s proof against a key `signer` lists under `relationship`.
   206	fn check_proof(document: &Value, signer: &Document, relationship: &[VerificationRelationship]) -> Result<(), VerifyError> {
   207	    let proof = document.get("proof").ok_or_else(|| malformed("proof"))?;
   208	    if proof.get("type").and_then(Value::as_str) == Some(ED25519_SIGNATURE_2020) {
   209	        let method = proof.get("verificationMethod").and_then(Value::as_str).ok_or_else(|| malformed("proof.verificationMethod"))?;
   210	        let key = listed_key(signer, relationship, method)?;
   211	        credential::verify_signature(document, &key).map_err(VerifyError::BadSignature)?;
   212	    }
   213	    Ok(())
   214	}
   215	
   216	fn listed_key(signer: &Document, relationship: &[VerificationRelationship], method: &str) -> Result<VerifyingKey, VerifyError> {
   217	    let unknown = || VerifyError::UnknownKey(method.to_string());
   218	    let absolute = |reference: &str| match reference.strip_prefix('#') {
   219	        Some(fragment) => format!("{}#{fragment}", signer.id),
   220	        None => reference.to_string(),
   221	    };
   222	    let listed = relationship.iter().find_map(|entry| match entry {
   223	        VerificationRelationship::Reference(reference) if absolute(reference) == method => {
   224	            signer.verification_method.iter().find(|vm| absolute(vm.id.as_str()) == method).cloned()
   225	        }
   226	        VerificationRelationship::VerificationMethod(vm) if absolute(vm.id.as_str()) == method => Some((**vm).clone()),
   227	        _ => None,
   228	    });
   229	    let vm = listed.ok_or_else(unknown)?;
   230	    match vm.decode_public_key() {
   231	        Ok((affinidi_encoding::ED25519_PUB, bytes)) => {
   232	            let bytes: [u8; 32] = bytes.try_into().map_err(|_| unknown())?;
   233	            VerifyingKey::from_bytes(&bytes).map_err(|_| unknown())
   234	        }
   235	        _ => Err(unknown()),
   236	    }
   237	}
   238	
   239	fn malformed(field: &str) -> VerifyError {
   240	    VerifyError::Malformed(format!("missing or invalid {field}"))
   241	}
   242	
   243	fn str_field<'a>(value: &'a Value, field: &str) -> Result<&'a str, VerifyError> {
   244	    value.get(field).and_then(Value::as_str).ok_or_else(|| malformed(field))
   245	}
   246	
   247	fn int_field(value: &Value, field: &str) -> Result<i64, VerifyError> {
   248	    value.get(field).and_then(Value::as_i64).ok_or_else(|| malformed(field))
   249	}
   250	
   251	fn unix_now() -> i64 {
   252	    std::time::SystemTime::now()
   253	        .duration_since(std::time::UNIX_EPOCH)
   254	        .map(|d| d.as_secs() as i64)
   255	        .unwrap_or_default()
   256	}
