     7	
     8	use std::sync::Arc;
     9	
    10	use credentials_backend::credential::{self, Disclosure};
    11	use credentials_backend::issuer::{CredentialRequest, IssuedCredential, Issuer};
    12	use credentials_backend::resolver::{did_key_for, Resolver};
    13	use credentials_backend::store::Store;
    14	use credentials_backend::transport::StaticTransport;
    15	use credentials_backend::verifier::{Submission, Verifier};
    16	use ed25519_dalek::SigningKey;
    17	use serde_json::{json, Value};
    18	
    19	pub const HARBOUR_DID: &str = "did:web:members.harbourclub.example";
    20	pub const HARBOUR_KEY_ID: &str = "did:web:members.harbourclub.example#key-1";
    21	pub const HARBOUR_SEED: &str = "9f3688f6e8b93b0cfa3b11c28fbc25fe5440192ed82835e7fe3ab590f03f6c75";
    22	pub const HARBOUR_PUBLIC: &str = "z6MkjgN85pffmWg8nS4P2epjg78ADoAaBs7jfzryUFx8vt6N";
    23	
    24	/// 2026-06-01T00:00:00Z — "now" for every verifier in the suite.
    25	pub const NOW: i64 = 1_780_272_000;
    26	pub const DAY: i64 = 86_400;
    27	
    28	pub const NONCE: &str = "n-0S6_WzA2Mj";
    29	pub const DOMAIN: &str = "door.harbourclub.example";
    30	
    31	pub fn seed(hex: &str) -> [u8; 32] {
    32	    let mut out = [0u8; 32];
    33	    for (i, byte) in out.iter_mut().enumerate() {
    34	        *byte = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap();
    35	    }
    36	    out
    37	}
    38	
    39	pub fn harbour() -> Issuer {
    40	    Issuer::new(HARBOUR_DID, HARBOUR_KEY_ID, &seed(HARBOUR_SEED))
    41	}
    42	
    43	pub struct Holder {
    44	    pub key: SigningKey,
    45	    pub did: String,
    46	}
    47	
    48	impl Holder {
    49	    pub fn new(seed_byte: u8) -> Self {
    50	        let key = SigningKey::from_bytes(&[seed_byte; 32]);
    51	        let did = did_key_for(&key.verifying_key());
    52	        Holder { key, did }
    53	    }
    54	
    55	    pub fn key_id(&self) -> String {
    56	        let fragment = self.did.trim_start_matches("did:key:");
    57	        format!("{}#{}", self.did, fragment)
    58	    }
    59	
    60	    /// Builds and signs a presentation of `issued`, disclosing the claims named in `reveal`.
    61	    pub fn present(&self, issued: &IssuedCredential, reveal: &[&str], nonce: &str, domain: &str) -> Value {
    62	        let disclosures: Vec<&Disclosure> =
    63	            issued.disclosures.iter().filter(|d| reveal.contains(&d.name.as_str())).collect();
    64	        let mut vp = json!({
    65	            "@context": ["https://www.w3.org/2018/credentials/v1"],
    66	            "type": ["VerifiablePresentation"],
    67	            "holder": self.did,
    68	            "verifiableCredential": issued.credential,
    69	            "disclosures": disclosures,
    70	            "nonce": nonce,
    71	            "domain": domain,
    72	        });
    73	        credential::sign(&mut vp, &self.key, &self.key_id(), "authentication", NOW);
    74	        vp
    75	    }
    76	}
    77	
    78	pub fn membership_request(holder: &Holder) -> CredentialRequest {
    79	    CredentialRequest {
    80	        holder: holder.did.clone(),
    81	        credential_type: "MembershipCredential".into(),
    82	        claims: vec![
    83	            ("member".into(), json!(true)),
    84	            ("tier".into(), json!("gold")),
    85	            ("birthdate".into(), json!("1990-04-12")),
    86	        ],
    87	        issued_at: NOW - 30 * DAY,
    88	        not_before: None,
    89	        expires_at: NOW + 180 * DAY,
    90	    }
    91	}
    92	
    93	pub fn store() -> Arc<Store> {
    94	    Arc::new(Store::from_onboarding_data().expect("onboarding data parses"))
    95	}
    96	
    97	pub fn harbour_document() -> Value {
    98	    json!({
    99	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
   100	        "id": HARBOUR_DID,
   101	        "verificationMethod": [{
   102	            "id": HARBOUR_KEY_ID,
   103	            "type": "Multikey",
   104	            "controller": HARBOUR_DID,
   105	            "publicKeyMultibase": HARBOUR_PUBLIC
   106	        }],
   107	        "authentication": [HARBOUR_KEY_ID],
   108	        "assertionMethod": [HARBOUR_KEY_ID],
   109	        "service": [{
   110	            "id": format!("{HARBOUR_DID}#site"),
   111	            "type": "LinkedDomains",
   112	            "serviceEndpoint": "https://harbourclub.example/"
   113	        }]
   114	    })
   115	}
   116	
   117	pub const HARBOUR_URL: &str = "https://members.harbourclub.example/.well-known/did.json";
   118	
   119	pub fn transport() -> StaticTransport {
   120	    StaticTransport::default().with(HARBOUR_URL, harbour_document().to_string())
   121	}
   122	
   123	pub fn verifier(store: Arc<Store>) -> Verifier {
   124	    let resolver = Resolver::new(Arc::new(transport()));
   125	    Verifier::new(resolver, store).with_clock(|| NOW)
   126	}
   127	
   128	pub fn submission(request_id: &str, presentation: Value) -> Submission {
   129	    Submission { request_id: request_id.into(), presentation }
   130	}
