     1	/// One salted claim the holder can reveal: its digest sits in the credential.
     2	class Disclosure {
     3	  const Disclosure({
     4	    required this.salt,
     5	    required this.name,
     6	    required this.value,
     7	  });
     8	
     9	  factory Disclosure.fromJson(Object? json) {
    10	    if (json is Map<String, dynamic>) {
    11	      return Disclosure(
    12	        salt: json['salt'] as String,
    13	        name: json['name'] as String,
    14	        value: json['value'],
    15	      );
    16	    }
    17	    if (json is List && json.length == 3) {
    18	      return Disclosure(
    19	        salt: json[0] as String,
    20	        name: json[1] as String,
    21	        value: json[2],
    22	      );
    23	    }
    24	    throw FormatException('Unrecognised disclosure: $json');
    25	  }
    26	
    27	  final String salt;
    28	  final String name;
    29	  final Object? value;
    30	
    31	  Map<String, dynamic> toJson() => {'salt': salt, 'name': name, 'value': value};
    32	}
    33	
    34	/// A credential in the wallet: the issuer-signed document plus the
    35	/// disclosures that go with it.
    36	class HeldCredential {
    37	  HeldCredential({required this.vc, required this.disclosures});
    38	
    39	  /// Parses the issuer's response: `{"credential": {...}, "disclosures": [...]}`.
    40	  factory HeldCredential.fromIssuance(Map<String, dynamic> json) {
    41	    final vc = json['credential'];
    42	    if (vc is! Map<String, dynamic>) {
    43	      throw const FormatException('Issuance response has no credential');
    44	    }
    45	    final disclosures = (json['disclosures'] as List? ?? const [])
    46	        .map(Disclosure.fromJson)
    47	        .toList();
    48	    return HeldCredential(vc: vc, disclosures: disclosures);
    49	  }
    50	
    51	  final Map<String, dynamic> vc;
    52	  final List<Disclosure> disclosures;
    53	
    54	  String get id => vc['id'] as String;
    55	
    56	  String get issuer {
    57	    final issuer = vc['issuer'];
    58	    return issuer is Map ? issuer['id'] as String : issuer as String;
    59	  }
    60	
    61	  String? get holderDid =>
    62	      (vc['credentialSubject'] as Map<String, dynamic>?)?['id'] as String?;
    63	
    64	  /// The most specific type, e.g. `MembershipCredential`.
    65	  String get type {
    66	    final types = vc['type'];
    67	    return types is List ? types.last as String : types as String;
    68	  }
    69	
    70	  Map<String, dynamic> toJson() => {
    71	    'credential': vc,
    72	    'disclosures': disclosures.map((d) => d.toJson()).toList(),
    73	  };
    74	}
