     5	/// The holder's signing key and the did:key derived from it.
     6	class HolderKey {
     7	  HolderKey._(this.keyPair) : did = DidKey.getDid(keyPair.publicKey);
     8	
     9	  /// A fresh random Ed25519 key.
    10	  factory HolderKey.generate() {
    11	    final (keyPair, _) = Ed25519KeyPair.generate();
    12	    return HolderKey._(keyPair);
    13	  }
    14	
    15	  /// A key restored from its 32-byte seed.
    16	  factory HolderKey.fromSeed(Uint8List seed) =>
    17	      HolderKey._(Ed25519KeyPair.fromSeed(seed));
    18	
    19	  final Ed25519KeyPair keyPair;
    20	  final String did;
    21	
    22	  /// The verification method id inside the did:key document.
    23	  String get keyId => '$did#${did.substring('did:key:'.length)}';
    24	
    25	  Future<Uint8List> sign(List<int> data) =>
    26	      keyPair.sign(Uint8List.fromList(data));
    27	
    28	  Future<bool> verify(List<int> data, List<int> signature) =>
    29	      keyPair.verify(Uint8List.fromList(data), Uint8List.fromList(signature));
    30	}
