    39	  /// Parses the issuer's response: `{"credential": {...}, "disclosures": [...]}`.
    40	  factory HeldCredential.fromIssuance(Map<String, dynamic> json) {
    41	    final vc = json['credential'];
    42	    if (vc is! Map<String, dynamic>) {
    43	      throw const FormatException('Issuance response has no credential');
    44	    }
    45	    final disclosures = (json['disclosures'] as List? ?? const [])
    46	        .map(Disclosure.fromJson)
    47	        .toList();
    48	    return HeldCredential(vc: vc, disclosures: disclosures);
    49	  }
